import DivisionSweeping from '../../../components/Division/sweeping/Division.sweeping';
import SectionCharacters from '../../../components/Section/characters/Section.characters';
import NavigationDefault from '../../../components/Navigation/default/Navigation.default';
import SectionDemonstration from '../../../components/Section/demonstration/Section.demonstration';

//--|🠋 Functions 🠋|--\\
import { stripBrackets } from '../../../tools/conversions';
import { loadPages } from '../../../tools/navigation';
import { checkScreen, synchDemo } from '../../../tools/synching';
import { loadAsset } from '../../../tools/utilities';
import previewProfile, { unfoldFooters, expandFooters, squareFooters, freezeFooters } from './HyperlinkFunctions';

interface InfoProps {
  info: {
    pageName: '[hyperlink]' | string;
    blockName: '<footer>' | string;
    labelName: '(default)' | '(demonstration)' | '(application)' | string;
  };
}
function HyperlinkFooter({ info }: InfoProps) {
  const [getOrientation, setOrientation] = useState<'landscape' | 'portrait'>(
    window.matchMedia('(orientation: landscape)').matches ? 'landscape' : 'portrait',
  ); //--|🠈 Updates state when the orientation changes 🠈|--\\
  const pageName = stripBrackets(info.pageName, '[]') as 'hyperlink';
  const blockName = stripBrackets(info.blockName, '<>') as 'footer';
  const labelName = stripBrackets(info.labelName, '()') as 'default';

  useEffect(() => {
    //--|🟥|--\\
    return checkScreen(setOrientation);
  }, [pageName, blockName, labelName]);

  let blurName: string = 'obnubilate';
  let stateName: 'expanded' | 'unfolded' | 'collapsed' | 'squaring';
  switch (getOrientation) {
    case 'landscape':
      stateName = 'unfolded';
      return (
        <footer
          id={`${pageName}-${blockName}`}
          className={`${blurName} ${labelName}-${blockName} ${stateName}`}
          onMouseEnter={(event) => {
            unfoldFooters(event.currentTarget);
          }}
          onMouseLeave={(event) => {
            squareFooters(event.currentTarget);
          }}
        >
          <section className={`${blockName}-foreground`}>
            <NavigationDefault
              //--|🠊 <nav class="default-footer_navigation-default"/> 🠈|--\\
              info={{
                pageName: pageName,
                blockName: blockName,
                labelName: labelName,
              }}
              style={{
                color: '(mono)',
                view: 'bot-rig',
                shade: '~dark~',
                image: loadAsset('-svg-', '/archive-images/my-signature/signature-icon/primary-dark') as string,
              }}
              cases={{
                view: undefined,
                image: undefined,
                tasks: {
                  onClick: (view) => {
                    switch (view) {
                      case 'bot-rig':
                        return loadPages('components');
                    }
                  },
                },
              }}
            />
            <MenuSelect
              info={{
                blockName: blockName as 'main',
                pageName: pageName as 'components',
                labelName: `${pageName}-applications` as string,
              }}
              style={{
                align: '-mid-',
                view: 'bot-cen',
                shade: '~dark~',
                color: ['(green)', '(blue)', '(orange)'], //--|🠊 AI Code: Review Please 2026-11-09 14:01 · TraLogFin logo in the company colour 🠈|--\\
                image: [
                  loadAsset('-svg-', '/tralogfin-application/track-a-day/primary-medium'),
                  loadAsset('-svg-', '/tralogfin-application/log-a-ticket/primary-medium'),
                  loadAsset('-svg-', '/tralogfin-application/pick-a-page/trinity-apps'),
                ] as Array<string>,
                size: '<h4>',
              }}
              cases={{
                pages: 3,
                axis: '[x]',
                link: undefined,
                task: [() => loadPages('overtime'), () => loadPages('ticketing'), () => loadPages('landing')],
              }}
            />
          </section>
          <figure className={`${blockName}-midground`}>
            <div className="bot"></div>
          </figure>
          <div className={`${blockName}-background`}></div>
        </footer>
      );
    case 'portrait':
      stateName = 'expanded';
      return (
        <footer
          id={`${pageName}-${blockName}`}
          className={`${blurName} ${labelName}-${blockName} ${stateName}`}
          onClick={(event) => {
            unfoldFooters(event.currentTarget); //--|🠈 Mobile taps to unfold, <main> folds it back 🠈|--\\
          }}
          onLoad={() => {
            synchDemo(pageName, blockName, 'load');
          }}
        >
          <section className={`${blockName}-foreground`}>
            <NavigationDefault
              //--|🠊 <nav class="default-footer_navigation-default"/> 🠈|--\\
              info={{
                pageName: pageName,
                blockName: blockName,
                labelName: labelName,
              }}
              style={{
                color: '(red)',
                view: 'bot-rig',
                shade: '~dark~',
                image: loadAsset('-svg-', '/tralogfin-application/find-a-link/primary-medium') as string,
              }}
              cases={{
                view: undefined,
                image: undefined,
                tasks: {
                  onClick: (_view, container) => {
                    expandFooters(container);
                    synchDemo(pageName, blockName, 'pick');
                  },
                },
              }}
            />

            <div className={`default-${blockName}_characters-demonstration`}>
              <AsideCharacters
                info={{
                  pageName: pageName,
                  blockName: blockName,
                  labelName: labelName,
                }}
                style={{
                  view: '-left-',
                  color: '(mono)',
                  shade: '~dark~',
                  clarity: '⟨opaque⟩',
                }}
                cases={{
                  task: [
                    (event) => previewProfile('enter', event.currentTarget as HTMLButtonElement, pageName, blockName, 'demo-left'),
                    (event) => previewProfile('click', event.currentTarget as HTMLButtonElement, pageName, blockName, 'demo-left'),
                    (event) => previewProfile('leave', event.currentTarget as HTMLButtonElement, pageName, blockName, 'demo-left'),
                  ],
                }}
              />
              <AsideCharacters
                info={{
                  pageName: pageName,
                  blockName: blockName,
                  labelName: labelName,
                }}
                style={{
                  view: '-right-',
                  color: '(mono)',
                  shade: '~light~',
                  clarity: '⟨opaque⟩',
                }}
                cases={{
                  task: [
                    (event) => previewProfile('enter', event.currentTarget as HTMLButtonElement, pageName, blockName, 'demo-right'),
                    (event) => previewProfile('click', event.currentTarget as HTMLButtonElement, pageName, blockName, 'demo-right'),
                    (event) => previewProfile('leave', event.currentTarget as HTMLButtonElement, pageName, blockName, 'demo-right'),
                  ],
                }}
              />
            </div>

            <MenuToggle
              info={{
                pageName: pageName,
                blockName: blockName,
                labelName: 'demonstration',
              }}
              style={{
                size: '<h3>',
                color: '(mono)',
                shade: ['~dark~', '~light~'],
                view: ['-left-', '-right-'],
                text: ['Specialist', 'Technician'],
                image: [
                  loadAsset('-svg-', '/archive-images/font-awesome/7.3.1/solid/award'),
                  loadAsset('-svg-', '/archive-images/font-awesome/7.3.1/solid/screwdriver-wrench'),
                ],
              }}
              cases={{
                task: [
                  {
                    click: () => synchDemo(pageName, blockName, 'click'),
                    enter: (event) => previewProfile('enter', event.currentTarget as HTMLButtonElement, pageName, blockName, 'demo-left'),
                  },
                  {
                    click: () => synchDemo(pageName, blockName, 'click'),
                    enter: (event) => previewProfile('enter', event.currentTarget as HTMLButtonElement, pageName, blockName, 'demo-right'),
                  },
                ],
              }}
            />
          </section>
          <figure className={`${blockName}-midground`}>
            <div className="top"></div>
            <DivisionSweeping
              //--|🠊 <div class="demon-left-footer_sweeping-default"/> 🠈|--\\
              info={{
                labelName: 'demo-left',
                blockName: blockName as '<footer>',
                pageName: pageName as '[hyperlink]',
              }}
              cases={{
                axis: '[y]',
                view: '-top-',
                show: 0 as number,
                call: HyperlinkCharacters as React.ComponentType<InfoProps>,
              }}
            />

            <SectionDemonstration
              info={{
                pageName: pageName,
                blockName: blockName,
                labelName: labelName,
              }}
              style={{
                shade: '~dark~',
                color: '(red)',
              }}
              cases={{
                apps: 'find-a-link',
              }}
            />

            <DivisionSweeping
              //--|🠊 <div class="demo-right-footer_sweeping-default"/> 🠈|--\\
              info={{
                labelName: 'demo-right',
                blockName: blockName as '<footer>',
                pageName: pageName as '[hyperlink]',
              }}
              cases={{
                axis: '[y]',
                view: '-bot-',
                show: 0 as number,
                call: HyperlinkCharacters as React.ComponentType<InfoProps>,
              }}
            />
            <div className="bot"></div>
          </figure>
          <div className={`${blockName}-background`}>
            <div className="lef"></div>
            <div className="rig"></div>
          </div>
        </footer>
      );
  }
}
